2730→    validate_dataset_name(&name)?;
2731→
2732→    let versions = state
2733→        .repo
2734→        .list_dataset_versions(&name)
2735→        .await
2736→        .map_err(AppError::internal)?;
2737→
2738→    let completeness_records = state
2739→        .repo
2740→        .list_completeness_by_dataset(&name)
2741→        .await
2742→        .map_err(AppError::internal)?;
2743→
2744→    let version_infos: Vec<DatasetVersionInfo> = versions
2745→        .iter()
2746→        .map(|v| DatasetVersionInfo {
2747→            id: v.id,
2748→            version: v.version,
2749→            status: v.status.to_string(),
2750→            parser_hash: v.parser_hash.clone(),
2751→            created_at: v.created_at.to_rfc3339(),
2752→            notes: v.notes.clone(),
2753→        })
2754→        .collect();
2755→
2756→    let active_version = version_infos.iter().find(|v| v.status == "active").cloned();
2757→
2758→    let completeness_infos: Vec<DatasetCompletenessInfo> = completeness_records
2759→        .iter()
2760→        .map(|c| DatasetCompletenessInfo {
2761→            target_id: c.target_id,
2762→            network: c.network.clone(),
2763→            status: c.status.to_string(),
