2766→            records_count: c.records_count,
2767→            last_ingestion_run_id: c.last_ingestion_run_id,
2768→        })
2769→        .collect();
2770→
2771→    Ok(Json(DatasetStatus {
2772→        name,
2773→        active_version,
2774→        versions: version_infos,
2775→        completeness: completeness_infos,
2776→    }))
