            network_activity: vec![NetworkActivity {
                network: "solana-mainnet".to_string(),
                entry_count: 10,
                unique_assets: 3,
                unique_counterparties: 2,
            }],
            type_breakdown: vec![TypeBreakdown {
                entry_type: "transfer".to_string(),
                count: 7,
