        args.add(tx.ingestion_run_id)
            .map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(tx.ingested_at)
            .map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
    Ok((query, args))
}

