             mode::text, label, owner_id, created_at, updated_at \
             FROM index_targets \
             WHERE kind = $1::target_kind_enum AND network = $2 AND address = $3",
        )
        .bind(target_kind_to_sql(&kind))
        .bind(network)
        .bind(address)
        .fetch_optional(self.pool())
        .await?;
        row.as_ref().map(row_to_index_target).transpose()
