fn validate_date_range(from: Option<i64>, to: Option<i64>) -> Result<(), AppError> {
    if let (Some(f), Some(t)) = (from, to) {
        if f > t {
            return Err(AppError::bad_request("'from' must be <= 'to'"));
        }
    }
