        let disp = response
            .headers()
            .get("content-disposition")
            .unwrap()
            .to_str()
            .unwrap();
        assert!(disp.contains("token_transfers"));
        assert!(disp.contains(".jsonl"));

        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], b"{\"test\":1}\n{\"test\":2}\n");
    }

