                .unwrap(),
            ))
            .unwrap();
        let resp1 = app.oneshot(req1).await.unwrap();
        assert_ne!(resp1.status(), StatusCode::SERVICE_UNAVAILABLE);

        tokio::time::sleep(Duration::from_millis(50)).await;

        let app2 = test_router_with_state(Arc::clone(&state));
