            .body(Body::from(body.to_string()))
            .unwrap();
        let resp = app.oneshot(req).await.unwrap();
        let status = resp.status();
        assert_ne!(
            status,
            StatusCode::NOT_FOUND,
            "POST {} should be routed (got 404)",
            uri
        );
        assert_ne!(
            status,
            StatusCode::UNAUTHORIZED,
            "POST {} should pass auth (got 401)",
            uri
        );
    }

