    #[test]
    fn test_build_checkpoint_solana() {
        let txs = vec![
            make_tx(
                Chain::Solana,
                "sig1",
                100,
                serde_json::json!({"slot": 5000}),
            ),
            make_tx(
                Chain::Solana,
                "sig2",
                200,
                serde_json::json!({"slot": 6000}),
            ),
        ];
        let cp = build_checkpoint("solana", "wallet", &txs).unwrap();
        assert!(matches!(cp.chain, Chain::Solana));
