    async fn test_local_file_sink_write_and_readback() {
        let dir = std::env::temp_dir().join(format!("spectraplex_test_{}", Uuid::new_v4()));
        tokio::fs::create_dir_all(&dir).await.unwrap();
        let path = dir.join("export.jsonl");

