                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "decoded_events" => {
            let records = state
                .repo
                .query_decoded_events(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_fills" => {
            let records = state
                .repo
                .query_hl_fill_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_funding" => {
            let records = state
                .repo
                .query_hl_funding_payments(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "positions" => {
            let records = state
                .repo
                .query_hl_position_changes(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "wallet_ledger" => {
            let records = state
                .repo
                .query_wallet_ledger_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "balance_history" => {
            let records = state
                .repo
                .query_balance_snapshots(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_pnl_summary" => {
            let records = state
                .repo
                .query_hl_pnl_summary(
                    params.target_id,
