        // fees: 2 + 1 = 3
        assert_eq!(s.total_fees, BigDecimal::from_str("3").unwrap());
        // net_pnl: 50 + 7.5 - 3 = 54.5
        assert_eq!(s.net_pnl, BigDecimal::from_str("54.5").unwrap());
        assert_eq!(s.fill_count, 2);
        assert_eq!(s.win_count, 1);
        assert_eq!(s.loss_count, 1);
